import { useContext } from "react";
import { ConfigContext } from '../config/config-provider'; // Import the ConfigContext
import { getDialogProps } from './dialog-props';
import { EMPTY_TEXT_CLASS, isEmptyContent, isTextDialog } from './empty-content';
import './../styles/uhuu-indicators.css';


interface EditableProps {
  className?: string;
  dialog?: object;
  children?: React.ReactNode;
}

/**
 * Binds its children to an edit dialog through `getDialogProps`.
 *
 * The element is rendered even when there is nothing to show: it is the only click target, so
 * a wrapper that returned null would leave an emptied field impossible to fill again. A text-bound
 * Editable whose children are empty (null, false, a whitespace-only string) is marked
 * `uhuu-text-empty`, which `uhuu-indicators.css` gives a one-line box in the editor. Templates
 * control print layout. Pass `null` rather than a renderer element around an empty string;
 * an element counts as content.
 */
const Editable = (props: EditableProps) => {
  const config = useContext(ConfigContext);
  // Only a text-bound element gets the marker, and the template's className is kept verbatim
  // (no class merging): a filled Editable renders exactly the markup it always did.
  const isEmpty = isTextDialog(props.dialog) && isEmptyContent(props.children);
  const className = isEmpty
    ? [props.className, EMPTY_TEXT_CLASS].filter(Boolean).join(' ')
    : props.className;

  return (
      <div
        className={className}
        {...getDialogProps(props, config)}
      >
        {props.children}
      </div>
  );
};

export default Editable;
